// Pre-router: detecta si el webhook recibe:
//   (a) url_verification challenge de Slack → marca is_challenge=true
//   (b) event_callback de Slack (mención en canal o DM) → arma body con message + campos slack
//   (c) llamada HTTP directa con campo message → pasa tal cual
const raw = $input.first().json || {};

// Localizar el body en varias ubicaciones posibles
let body = null;
if (raw.type) body = raw;
else if (raw.body && typeof raw.body === 'object' && (raw.body.type || raw.body.message || raw.body.event)) body = raw.body;
else if (raw.body && typeof raw.body === 'string') { try { body = JSON.parse(raw.body); } catch(e){} }
if (!body) body = raw.body || raw;

// ── 1) Challenge de verificación de Slack ──
if (body.type === 'url_verification') {
  return [{ json: { is_challenge: true, challenge: body.challenge || '' } }];
}

// ── 2) Evento real de Slack (event_callback con un app_mention o mensaje en DM) ──
if (body.type === 'event_callback' && body.event) {
  const ev = body.event;
  // Filtrar: ignorar mensajes del propio bot y subtipos como join/leave
  if (ev.bot_id || ev.subtype) {
    return [{ json: { is_challenge: false, skip: true, reason: 'bot_or_subtype' } }];
  }
  // Limpiar la mención del bot del texto (ej. <@U123ABC> ¿pregunta?)
  const cleanText = (ev.text || '').replace(/<@[A-Z0-9]+>/gi, '').trim();
  if (!cleanText) {
    return [{ json: { is_challenge: false, skip: true, reason: 'empty_text' } }];
  }
  return [{ json: {
    is_challenge: false,
    skip: false,
    // Campos que espera 'Normalizar input'
    body: {
      message: cleanText,
      session_id: ev.user || ev.channel || 'default',
      slack_channel_id: ev.channel || null,
      slack_thread_ts:  ev.thread_ts || null,
      slack_msg_ts:     ev.ts || null,
      slack_user:       ev.user || null
    }
  } }];
}

// ── 3) Llamada HTTP directa (curl, otro workflow, etc.) → pasa tal cual ──
return [{ json: { is_challenge: false, skip: false, body: body, headers: raw.headers } }];

// Normaliza el input: HTTP directo o evento Slack (ya pre-procesado por Pre-router Slack)
const raw = $input.first().json || {};

// Defensivo: si el Pre-router marcó skip=true, descartamos silenciosamente
if (raw.skip === true || raw.is_challenge === true) {
  return [];
}

const body = raw.body?.message || raw.body?.text || raw.body?.query || raw.body?.pregunta
  ? raw.body
  : (raw.body?.body || raw.body || raw);

const message = body.message || body.text || body.query || body.pregunta || body.input || '';
const session_id = body.session_id || body.user_id || raw.headers?.['x-session-id'] || 'default';

// Campos Slack (solo presentes si viene de Slack)
const slack_channel_id = body.slack_channel_id || null;
const slack_thread_ts  = body.slack_thread_ts  || null;
const slack_msg_ts     = body.slack_msg_ts     || null;
const slack_user       = body.slack_user       || null;

// Detectar si la pregunta vino DENTRO de un hilo existente
const is_thread_reply = !!slack_thread_ts && slack_thread_ts !== slack_msg_ts;

if (!message || !String(message).trim()) {
  // En vez de tirar, descartar silenciosamente (evita ejecuciones rotas por payloads vacíos)
  return [];
}
return [{ json: { message: String(message).trim(), session_id, slack_channel_id, slack_thread_ts, slack_msg_ts, slack_user, is_thread_reply } }];

const agentOutput = $('Agente OPEX (Claude)').first().json.output || 'Sin respuesta del agente.';
const input = $('Normalizar input').first().json;
const channelId    = input.slack_channel_id;
const threadTs     = input.slack_thread_ts;
const msgTs        = input.slack_msg_ts;
const slackUser    = input.slack_user || '';
const replyThreadTs = threadTs || msgTs;

let memory_id = null;
try { memory_id = $('Guardar en memoria').first().json.id; } catch(e) {}

// Convertir markdown → Slack mrkdwn
let text = agentOutput
  .replace(/\*\*(.+?)\*\*/g, '*$1*')
  .replace(/#{1,3}\s+(.+)/g, '*$1*')
  .replace(/^---+$/gm, '')
  .trim();

// Dividir en chunks de máx 2900 chars cortando en salto de línea
// Se envían como bloques DENTRO de un mismo mensaje → orden garantizado
const MAX = 2900;
function splitChunks(str) {
  const chunks = [];
  while (str.length > MAX) {
    let cut = str.lastIndexOf('\n', MAX);
    if (cut < MAX * 0.5) cut = MAX;
    chunks.push(str.slice(0, cut).trim());
    str = str.slice(cut).trim();
  }
  if (str) chunks.push(str);
  return chunks;
}
const chunks = splitChunks(text);

// Construir bloques: un section por chunk + header en el primero
const blocks = [];
chunks.forEach((chunk, i) => {
  const content = i === 0
    ? `🔮 *Oráculo del OPEX*\n\n${chunk}`
    : chunk;
  blocks.push({ type: 'section', text: { type: 'mrkdwn', text: content } });
  // Divisor entre bloques (no al final)
  if (i < chunks.length - 1) blocks.push({ type: 'divider' });
});

// Feedback y firma al final
if (memory_id && channelId) {
  blocks.push({
    type: 'actions',
    elements: [
      { type: 'button', text: { type: 'plain_text', text: '👍 Útil' }, value: `good_${memory_id}`, action_id: 'feedback_good' },
      { type: 'button', text: { type: 'plain_text', text: '👎 Mejorar' }, value: `bad_${memory_id}`, action_id: 'feedback_bad' }
    ]
  });
}
blocks.push({
  type: 'context',
  elements: [{ type: 'mrkdwn', text: `Powered by Claude Sonnet${slackUser ? ' · <@' + slackUser + '>' : ''}` }]
});

const payload = {
  channel: channelId,
  text: `🔮 Oráculo del OPEX: ${text.slice(0, 200)}`,  // fallback para notificaciones
  blocks
};
if (replyThreadTs) payload.thread_ts = replyThreadTs;

return [{ json: { payload } }];

const input = $('Normalizar input').first().json;
const message = input.message;

let history = [], prefs = { response_style: 'balanced', notes: '' };

try {
  const ctx = $('Cargar contexto usuario').first().json;
  if (ctx.history && Array.isArray(ctx.history)) history = ctx.history;
  if (ctx.prefs && typeof ctx.prefs === 'object') prefs = { ...prefs, ...ctx.prefs };
} catch(e) {}

// Mensaje padre del hilo (si la pregunta vino dentro de un hilo existente)
let parentText = '';
try {
  const parentRes = $('Fetch hilo padre').first().json;
  if (input.is_thread_reply && parentRes && parentRes.ok && Array.isArray(parentRes.messages) && parentRes.messages[0]) {
    const t = (parentRes.messages[0].text || '').replace(/<@[A-Z0-9]+>/gi, '').trim();
    if (t) parentText = t;
  }
} catch (e) {}

// Fecha actual en zona horaria Colombia
const now = new Date();
const bogotaDate = new Intl.DateTimeFormat('es-CO', {
  weekday: 'long', year: 'numeric', month: 'long', day: 'numeric',
  timeZone: 'America/Bogota'
}).format(now);
const isoDate = new Intl.DateTimeFormat('en-CA', {
  year: 'numeric', month: '2-digit', day: '2-digit',
  timeZone: 'America/Bogota'
}).format(now);
const yyyy = isoDate.slice(0, 4);
const mm = isoDate.slice(5, 7);
const prevMonth = new Date(parseInt(yyyy), parseInt(mm) - 1 - 1, 1);
const prevMonthLabel = prevMonth.toLocaleDateString('es-CO', { year: 'numeric', month: 'long', timeZone: 'America/Bogota' });

let contextBlock = `[FECHA ACTUAL]\nHoy es ${bogotaDate} (${isoDate}, zona horaria America/Bogota).\n\"Hoy\" = ${isoDate}. \"Este mes\" = ${yyyy}-${mm}. \"El mes pasado\" = ${prevMonthLabel}.\nUsa SIEMPRE estas referencias para resolver fechas relativas. Ignora cualquier conocimiento previo sobre la fecha.\n[/FECHA ACTUAL]\n\n`;

if (parentText) {
  contextBlock += `[MENSAJE PADRE DEL HILO]\nEl usuario te tagueó dentro de un hilo. El mensaje original que abrió el hilo es:\n\"${parentText.slice(0, 1500)}\"\nUsa este mensaje original como contexto principal a menos que la pregunta actual indique otra cosa.\n[/MENSAJE PADRE]\n\n`;
}

if (history.length > 0) {
  const lines = history.map(h =>
    `• \"${h.question.slice(0, 100)}\" ${h.rating || ''}\n  → ${h.answer.slice(0, 250)}...`
  ).join('\n');
  contextBlock += `[HISTORIAL RECIENTE]\n${lines}\n[/HISTORIAL]\n\n`;
}

const style = prefs.response_style || 'balanced';
const notes = prefs.notes || '';
contextBlock += `[PREFERENCIAS] Estilo: ${style}.${notes ? ' ' + notes : ''} [/PREFERENCIAS]\n\n`;

const enrichedMessage = contextBlock + 'Pregunta actual: ' + message;

return [{ json: { ...input, message: enrichedMessage } }];

// Retorna el output del agente al workflow padre (WF-G).
// Cuando WF-B es llamado via Execute Workflow, el padre recibe
// el output de todos los nodos hoja — este nodo garantiza que
// el campo 'output' esté disponible para Parse Sections en WF-G.
const agentOutput = $('Agente OPEX (Claude)').first()?.json?.output || '';
return [{ json: { output: agentOutput } }];

// Selecciona aleatoriamente una frase mística para mostrar que el oráculo está trabajando
// Se ejecuta ANTES de Normalizar input, así que lee los datos del Pre-router Slack
const frases = [
  '🔮 Consultando los telares del conocimiento...',
  '🔮 Las nebulosas del OPEX se alinean... permíteme un momento.',
  '🔮 Desentrañando los pergaminos sagrados del backlog...',
  '🔮 Las estrellas del OPEX están hablando... escuchando atentamente.',
  '🔮 Invocando los registros antiguos de Metabase y Supabase...',
  '🔮 El cristal mágico se ilumina... revelando la respuesta.',
  '🔮 Cruzando los hilos del tiempo y los datos... un momento.',
  '🔮 Despertando a los espíritus de la base de datos...',
  '🔮 Recorriendo los pergaminos digitales en busca de tu verdad...',
  '🔮 Los vientos del CAC murmuran respuestas... afinando el oído.'
];

// El input viene del Pre-router Slack (vía IF Es Slack Event)
// Formato: { is_challenge: false, skip: false, body: { slack_channel_id, slack_thread_ts, slack_msg_ts, ... } }
const raw = $input.first().json || {};
const slackData = raw.body || {};

const channelId = slackData.slack_channel_id;
const replyTs = slackData.slack_thread_ts || slackData.slack_msg_ts;

// Si por alguna razón no hay channel_id, descartamos
if (!channelId) {
  return [];
}

const frase = frases[Math.floor(Math.random() * frases.length)];

const payload = { channel: channelId, text: frase };
if (replyTs) payload.thread_ts = replyTs;

return [{ json: { payload } }];
